+class ModalDialog {
+    constructor() {
+        this.modal = document.getElementById('deleteModal');
+        this.overlay = this.modal.querySelector('.modal-overlay');
+        this.closeBtn = this.modal.querySelector('.modal-close');
+        this.cancelBtn = document.getElementById('cancelBtn');
+        this.confirmBtn = document.getElementById('confirmBtn');
+        this.triggers = document.querySelectorAll('.trigger');
+        this.currentImageCard = null;
+
+        this.init();
+    }
+
+    init() {
+        // Attach click handlers to all trigger buttons
+        this.triggers.forEach(trigger => {
+            trigger.addEventListener('click', () => this.open(trigger));
+        });
+
+        // Close button handlers
+        this.closeBtn.addEventListener('click', () => this.close());
+        this.cancelBtn.addEventListener('click', () => this.close());
+        this.overlay.addEventListener('click', () => this.close());
+
+        // Confirm button handler
+        this.confirmBtn.addEventListener('click', () => this.handleDelete());
+
+        // Prevent closing when clicking modal content
+        this.modal.querySelector('.modal-content').addEventListener('click', (e) => {
+            e.stopPropagation();
+        });
+
+        // Keyboard shortcuts
+        document.addEventListener('keydown', (e) => {
+            if (e.key === 'Escape' && this.isOpen()) {
+                this.close();
+            }
+        });
+    }
+
+    open(trigger) {
+        this.currentImageCard = trigger.closest('.image-card');
+        this.modal.classList.add('active');
+        this.modal.setAttribute('aria-hidden', 'false');
+        document.body.style.overflow = 'hidden';
+
+        // Focus the confirm button for accessibility
+        this.confirmBtn.focus();
+    }
+
+    close() {
+        this.modal.classList.remove('active');
+        this.modal.setAttribute('aria-hidden', 'true');
+        document.body.style.overflow = 'auto';
+        this.currentImageCard = null;
+    }
+
+    isOpen() {
+        return this.modal.classList.contains('active');
+    }
+
+    handleDelete() {
+        if (this.currentImageCard) {
+            // Get the image title for feedback
+            const title = this.currentImageCard.querySelector('h3').textContent;
+
+            // Remove the image card with a fade animation
+            this.currentImageCard.style.transition = 'opacity 0.3s ease';
+            this.currentImageCard.style.opacity = '0';
+
+            setTimeout(() => {
+                this.currentImageCard.remove();
+                this.close();
+                this.showDeleteNotification(title);
+            }, 300);
+        }
+    }
+
+    showDeleteNotification(title) {
+        // Create a temporary notification
+        const notification = document.createElement('div');
+        notification.className = 'notification';
+        notification.setAttribute('role', 'status');
+        notification.setAttribute('aria-live', 'polite');
+        notification.textContent = `"${title}" has been deleted.`;
+        document.body.appendChild(notification);
+
+        // Show notification
+        setTimeout(() => notification.classList.add('show'), 10);
+
+        // Remove notification after 3 seconds
+        setTimeout(() => {
+            notification.classList.remove('show');
+            setTimeout(() => notification.remove(), 300);
+        }, 3000);
+    }
+}
+
+// Initialize modal when DOM is ready
+if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', () => {
+        new ModalDialog();
+    });
+} else {
+    new ModalDialog();
+}
+
